import{_ as t,o as d,c as l,a5 as a}from"./chunks/framework.a5no_H3L.js";const m=JSON.parse('{"title":"常用数据类型速查","description":"本页只记录常用类型的长度、存储和比较语义。字符集与排序规则见字符集与排序规则，字段与主键选择见索引设计。","frontmatter":{},"headers":[],"relativePath":"mysql/reference/types.md","filePath":"mysql/reference/types.md"}'),s={name:"mysql/reference/types.md"};function r(c,e,i,n,f,y){return d(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="常用数据类型速查" tabindex="-1" data-src-line="1" data-src-file="mysql/reference/types.md">常用数据类型速查 <a class="header-anchor" href="#常用数据类型速查" aria-label="Permalink to &quot;常用数据类型速查&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="mysql/reference/types.md"><p data-src-line="3" data-src-file="mysql/reference/types.md">本页只记录常用类型的长度、存储和比较语义。字符集与排序规则见<a href="./../01-basics/chapter-03-charset-collation.html">字符集与排序规则</a>，字段与主键选择见<a href="./../03-index/chapter-02-index-design.html">索引设计</a>。</p></blockquote><h2 id="数值类型" tabindex="-1" data-src-line="5" data-src-file="mysql/reference/types.md">数值类型 <a class="header-anchor" href="#数值类型" aria-label="Permalink to &quot;数值类型&quot;">​</a></h2><table tabindex="0"><thead data-src-line="7" data-src-file="mysql/reference/types.md"><tr data-src-line="7" data-src-file="mysql/reference/types.md"><th style="text-align:left;">类型</th><th style="text-align:left;">存储</th><th style="text-align:left;">范围与说明</th></tr></thead><tbody data-src-line="9" data-src-file="mysql/reference/types.md"><tr data-src-line="9" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>TINYINT</code></td><td style="text-align:left;">1 字节</td><td style="text-align:left;">有符号 -128 ～ 127；无符号 0 ～ 255</td></tr><tr data-src-line="10" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>SMALLINT</code></td><td style="text-align:left;">2 字节</td><td style="text-align:left;">有符号 -32768 ～ 32767；无符号 0 ～ 65535</td></tr><tr data-src-line="11" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>MEDIUMINT</code></td><td style="text-align:left;">3 字节</td><td style="text-align:left;">有符号 -8388608 ～ 8388607；无符号 0 ～ 16777215</td></tr><tr data-src-line="12" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>INT</code></td><td style="text-align:left;">4 字节</td><td style="text-align:left;">有符号 -2^31 ～ 2^31-1；无符号 0 ～ 2^32-1</td></tr><tr data-src-line="13" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>BIGINT</code></td><td style="text-align:left;">8 字节</td><td style="text-align:left;">有符号 -2^63 ～ 2^63-1；无符号 0 ～ 2^64-1</td></tr><tr data-src-line="14" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>FLOAT</code></td><td style="text-align:left;">4 字节</td><td style="text-align:left;">单精度近似浮点，不用于精确比较</td></tr><tr data-src-line="15" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>DOUBLE</code></td><td style="text-align:left;">8 字节</td><td style="text-align:left;">双精度近似浮点，不用于精确比较</td></tr><tr data-src-line="16" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>DECIMAL(M,D)</code></td><td style="text-align:left;">按数字组打包</td><td style="text-align:left;">定点数；<code>M</code> 为总位数，<code>D</code> 为小数位</td></tr></tbody></table><p data-src-line="18" data-src-file="mysql/reference/types.md"><code>AUTO_INCREMENT</code> 用于整数和近似浮点类型，但生产主键通常使用整数类型。业务范围不足时不能依赖 <code>UNSIGNED</code> 掩盖设计问题。</p><h2 id="字符串类型" tabindex="-1" data-src-line="20" data-src-file="mysql/reference/types.md">字符串类型 <a class="header-anchor" href="#字符串类型" aria-label="Permalink to &quot;字符串类型&quot;">​</a></h2><table tabindex="0"><thead data-src-line="22" data-src-file="mysql/reference/types.md"><tr data-src-line="22" data-src-file="mysql/reference/types.md"><th style="text-align:left;">类型</th><th style="text-align:left;">声明上限</th><th style="text-align:left;">存储与说明</th></tr></thead><tbody data-src-line="24" data-src-file="mysql/reference/types.md"><tr data-src-line="24" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>CHAR(N)</code></td><td style="text-align:left;">0 ～ 255 <strong>个字符</strong></td><td style="text-align:left;">固定长度字符；不足时按排序规则补空格，检索时默认移除尾随空格</td></tr><tr data-src-line="25" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>VARCHAR(N)</code></td><td style="text-align:left;">0 ～ 65535 <strong>个字符</strong></td><td style="text-align:left;">变长字符；另存 1 或 2 字节长度前缀，实际上限还受行大小和字符集约束</td></tr><tr data-src-line="26" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>TINYTEXT</code></td><td style="text-align:left;">255 字节</td><td style="text-align:left;">小文本；多字节字符会占用更多字节</td></tr><tr data-src-line="27" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>TEXT</code></td><td style="text-align:left;">65535 字节</td><td style="text-align:left;">常规文本；有效字符数随字符集变化</td></tr><tr data-src-line="28" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>MEDIUMTEXT</code></td><td style="text-align:left;">16777215 字节</td><td style="text-align:left;">中等长度文本</td></tr><tr data-src-line="29" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>LONGTEXT</code></td><td style="text-align:left;">约 4 GB</td><td style="text-align:left;">超长文本</td></tr><tr data-src-line="30" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>BLOB</code></td><td style="text-align:left;">65535 字节</td><td style="text-align:left;">二进制大对象；长度按字节计算</td></tr><tr data-src-line="31" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>JSON</code></td><td style="text-align:left;">最大长度受行和文档限制</td><td style="text-align:left;">二进制 JSON 文档，解析、排序和部分函数行为与文本字符串不同</td></tr></tbody></table><p data-src-line="33" data-src-file="mysql/reference/types.md"><code>CHAR(N)</code> 中的 <code>N</code> 不是字节数。例如在 <code>utf8mb4</code> 下，一个字符最多占 4 字节，<code>CHAR(255)</code> 可容纳 255 个字符，存储空间会随字符集和填充规则变化。</p><p data-src-line="35" data-src-file="mysql/reference/types.md"><code>VARCHAR(65535)</code> 也不能作为单列可声明的通用上限。单行所有列的长度字节数受 65,535 字节约束；使用 <code>utf8mb4</code> 时，单个 <code>VARCHAR</code> 列的最大可声明字符数远低于 65,535。</p><h3 id="text-的默认值" tabindex="-1" data-src-line="37" data-src-file="mysql/reference/types.md">TEXT 的默认值 <a class="header-anchor" href="#text-的默认值" aria-label="Permalink to &quot;TEXT 的默认值&quot;">​</a></h3><ul data-src-line="39" data-src-file="mysql/reference/types.md"><li data-src-line="39" data-src-file="mysql/reference/types.md">MySQL 8.0.13 之前，<code>BLOB</code>、<code>TEXT</code>、<code>GEOMETRY</code> 和 <code>JSON</code> 类型不能使用 <code>DEFAULT</code>。</li><li data-src-line="40" data-src-file="mysql/reference/types.md">MySQL 8.0.13 起，这些类型可以使用括号中的表达式作为默认值，例如 <code>DEFAULT (JSON_OBJECT())</code>；不能把普通字符串字面量直接当作 <code>TEXT DEFAULT</code>。</li></ul><p data-src-line="42" data-src-file="mysql/reference/types.md">迁移到新版本前应以目标版本 DDL 为准，不要假设旧行为会自动改变。</p><h2 id="日期与时间类型" tabindex="-1" data-src-line="44" data-src-file="mysql/reference/types.md">日期与时间类型 <a class="header-anchor" href="#日期与时间类型" aria-label="Permalink to &quot;日期与时间类型&quot;">​</a></h2><table tabindex="0"><thead data-src-line="46" data-src-file="mysql/reference/types.md"><tr data-src-line="46" data-src-file="mysql/reference/types.md"><th style="text-align:left;">类型</th><th style="text-align:left;">形式</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="48" data-src-file="mysql/reference/types.md"><tr data-src-line="48" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>DATE</code></td><td style="text-align:left;"><code>YYYY-MM-DD</code></td><td style="text-align:left;">仅日期</td></tr><tr data-src-line="49" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>TIME</code></td><td style="text-align:left;"><code>HH:MM:SS</code></td><td style="text-align:left;">时间或时间差，可配置小数秒精度</td></tr><tr data-src-line="50" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>DATETIME</code></td><td style="text-align:left;"><code>YYYY-MM-DD HH:MM:SS</code></td><td style="text-align:left;">不带时区；可配置小数秒精度，范围较宽</td></tr><tr data-src-line="51" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>TIMESTAMP</code></td><td style="text-align:left;"><code>YYYY-MM-DD HH:MM:SS</code></td><td style="text-align:left;">存储 UTC 值，按会话时区转换；范围为 1970-01-01 到 2038-01-19</td></tr><tr data-src-line="52" data-src-file="mysql/reference/types.md"><td style="text-align:left;"><code>YEAR</code></td><td style="text-align:left;"><code>YYYY</code> 或 2 位数字形式</td><td style="text-align:left;">年份类型，按配置解释两位年份</td></tr></tbody></table><p data-src-line="54" data-src-file="mysql/reference/types.md">应用若需要无歧义的日期时间，应让数据库、JDBC、应用和 JVM 使用一致的时区策略，并在接口上明确时区或偏移量。</p><h2 id="选型原则" tabindex="-1" data-src-line="56" data-src-file="mysql/reference/types.md">选型原则 <a class="header-anchor" href="#选型原则" aria-label="Permalink to &quot;选型原则&quot;">​</a></h2><ul data-src-line="58" data-src-file="mysql/reference/types.md"><li data-src-line="58" data-src-file="mysql/reference/types.md">主键优先选择紧凑、单调或时间有序的值；随机 UUID 可能造成聚簇索引写放大，UUIDv7 等时间有序标识可以作为替代评估。</li><li data-src-line="59" data-src-file="mysql/reference/types.md">金额、汇率和账务计算使用 <code>DECIMAL</code>，不要用 <code>FLOAT</code> 或 <code>DOUBLE</code> 承担精确计算。</li><li data-src-line="60" data-src-file="mysql/reference/types.md"><code>BOOLEAN</code> 是 <code>TINYINT(1)</code> 的同义类型；如果使用 <code>TINYINT</code> 表示状态，应定义允许值或约束，不依赖显示宽度表达业务语义。</li><li data-src-line="61" data-src-file="mysql/reference/types.md">枚举值稳定且集合很小时可评估 <code>ENUM</code>；状态经常扩展或需要集中维护时，通常使用整数/字符码加应用字典。</li><li data-src-line="62" data-src-file="mysql/reference/types.md"><code>DATETIME</code> 适合记录无时区业务时间；需要自动 UTC 转换或覆盖 2038 边界时评估 <code>TIMESTAMP</code>，同时确认目标业务范围。</li><li data-src-line="63" data-src-file="mysql/reference/types.md">二级索引可以直接覆盖 <code>VARCHAR</code>；对 <code>BLOB</code>/<code>TEXT</code> 建普通二级索引必须指定前缀长度，索引只包含前缀。需要完整文本检索时使用 <code>FULLTEXT</code>，前缀索引不能替代全文语义。</li></ul>',17)])])}const x=t(s,[["render",r]]);export{m as __pageData,x as default};
